/**
 * Archives several issues at once. Ids outside the org, unknown ids and
 * already-archived ids are skipped and left untouched. Every issue to be
 * archived must pass the same `issue:archive` check as a single archive, and
 * all of them are checked before the first write, so one denial archives
 * nothing and publishes nothing.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requested = [...new Set(input.issueIds)];
  const found = new Map(
    (await issueRepo.findIssuesByIds(input.orgId, requested)).map(
      (issue) => [issue.id, issue] as const,
    ),
  );

  const skipped: IssueId[] = [];
  const targets: Issue[] = [];
  for (const issueId of requested) {
    const issue = found.get(issueId);
    if (issue === undefined || isArchived(issue)) {
      skipped.push(issueId);
    } else {
      targets.push(issue);
    }
  }

  for (const issue of targets) {
    assertCan(actor, "issue:archive", issueResource(issue));
  }

  const archived: Issue[] = [];
  for (const issue of targets) {
    archived.push(await issueRepo.archiveIssue(input.orgId, issue.id));
  }

  for (const issue of archived) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: issue.id,
      projectId: issue.projectId,
    });
  }

  return { archived: archived.map((issue) => issue.id), skipped };
}

